# npm scopes where every package belongs to one service.
KNOWN_SCOPES: dict[str, tuple[str, str]] = {
    "@supabase/": ("Supabase", "database"),
    "@clerk/": ("Clerk", "auth"),
    "@auth0/": ("Auth0", "auth"),
    "@kinde-oss/": ("Kinde", "auth"),
    "@firebase/": ("Firebase", "database"),
