"""Steps 5-7: bootstrap intervals, monthly cost projection, verdict."""
from __future__ import annotations

import random
import re
from dataclasses import dataclass, field

MEAN_TOLERANCE = 0.3     # "not meaningfully worse": mean within this many points...
MIN_SCORED = 10          # ...and at least this many scored outputs per model
MAX_ERROR_RATE = 0.10    # a model failing more often than this is not a viable choice


def bootstrap_ci(scores: list[float], n_boot: int = 2000, seed: int = 0,
                 alpha: float = 0.05) -> tuple[float, float, float]:
    """(mean, low, high) with a percentile bootstrap interval."""
    if not scores:
        return float("nan"), float("nan"), float("nan")
    mean = sum(scores) / len(scores)
    if len(scores) == 1:
        return mean, mean, mean
    rng = random.Random(seed)
    n = len(scores)
    means = sorted(sum(rng.choices(scores, k=n)) / n for _ in range(n_boot))
    lo = means[int(alpha / 2 * n_boot)]
    hi = means[min(n_boot - 1, int((1 - alpha / 2) * n_boot))]
    return mean, lo, hi


@dataclass
class ModelStats:
    model: str
    calls: int
    errors: int
    scored: int
    mean: float
    lo: float
    hi: float
    avg_latency_s: float
    avg_cost: float
    avg_input_tokens: float
    avg_output_tokens: float
    monthly_cost: float | None = None
    fits_budget: bool | None = None

    @property
    def error_rate(self) -> float:
        return self.errors / self.calls if self.calls else 1.0


def summarize(rows, models: list[str], seed: int = 0) -> dict[str, ModelStats]:
    out = {}
    for m in models:
        mine = [r for r in rows if r.model == m]
        ok = [r for r in mine if not r.error]
        scores = [r.score for r in ok if r.score is not None]
        mean, lo, hi = bootstrap_ci(scores, seed=seed)
        avg = (lambda xs: sum(xs) / len(xs) if xs else 0.0)
        out[m] = ModelStats(
            model=m, calls=len(mine), errors=len(mine) - len(ok), scored=len(scores),
            mean=mean, lo=lo, hi=hi,
            avg_latency_s=avg([r.latency_s for r in ok]), avg_cost=avg([r.cost for r in ok]),
            avg_input_tokens=avg([r.input_tokens for r in ok]),
            avg_output_tokens=avg([r.output_tokens for r in ok]))
    return out


def parse_number(text: str | None) -> float | None:
    """'500', '1,200', '1.5k', '$25/month', '2M' -> float."""
    if not text:
        return None
    m = re.search(r"(\d[\d,]*(?:\.\d+)?)\s*([kKmM])?", text)
    if not m:
        return None
    value = float(m.group(1).replace(",", ""))
    return value * {"k": 1e3, "m": 1e6}.get((m.group(2) or "").lower(), 1)


def project_monthly(stats: dict[str, ModelStats], users: float | None,
                    calls_per_user: float, budget: float | None) -> None:
    for s in stats.values():
        if users is None:
            continue
        s.monthly_cost = users * calls_per_user * s.avg_cost
        s.fits_budget = None if budget is None else s.monthly_cost <= budget


@dataclass
class Verdict:
    kind: str                     # keep | switch | insufficient
    chosen: str
    recommended: str
    summary: str
    rejected: dict[str, str] = field(default_factory=dict)


def _fmt(s: ModelStats) -> str:
    return f"{s.mean:.2f} [{s.lo:.2f}-{s.hi:.2f}]"


def decide(stats: dict[str, ModelStats], chosen: str) -> Verdict:
    c = stats[chosen]
    if c.scored < MIN_SCORED or c.error_rate > MAX_ERROR_RATE:
        return Verdict("insufficient", chosen, chosen,
                       f"Not enough evidence: only {c.scored} scored outputs for {chosen} "
                       f"({c.errors} errors).",
                       {m: "not evaluated: the chosen model's own results are incomplete"
                        for m in stats if m != chosen})

    def viable(s: ModelStats) -> bool:
        return s.scored >= MIN_SCORED and s.error_rate <= MAX_ERROR_RATE

    def close_by_mean(s: ModelStats) -> bool:
        return s.mean >= c.mean - MEAN_TOLERANCE

    def overlaps(s: ModelStats) -> bool:
        return s.hi >= c.lo and s.lo <= c.hi

    acceptable = [s for s in stats.values()
                  if s.model == chosen or (viable(s) and (close_by_mean(s) or overlaps(s)))]
    best = min(acceptable, key=lambda s: s.avg_cost)

    rejected = {}
    for s in stats.values():
        if s.model in (chosen, best.model):
            continue
        if not viable(s):
            rejected[s.model] = (f"unreliable: {s.errors}/{s.calls} calls failed, "
                                 f"{s.scored} scored")
        elif s not in acceptable:
            rejected[s.model] = (f"quality {_fmt(s)} is meaningfully below {chosen} {_fmt(c)}")
        else:
            rejected[s.model] = (f"similar quality {_fmt(s)} but ${s.avg_cost:.6f}/call vs "
                                 f"${best.avg_cost:.6f} for {best.model}")

    if best.model == chosen:
        return Verdict("keep", chosen, chosen,
                       f"Keep {chosen}: no cheaper candidate matched its quality {_fmt(c)}.",
                       rejected)
    ratio = c.avg_cost / best.avg_cost if best.avg_cost else float("inf")
    if close_by_mean(best):
        return Verdict("switch", chosen, best.model,
                       f"Switch to {best.model}: quality {_fmt(best)} vs {_fmt(c)} for "
                       f"{chosen} (within {MEAN_TOLERANCE} points), at {ratio:.1f}x lower "
                       f"cost per call.", rejected)
    return Verdict("insufficient", chosen, best.model,
                   f"Not enough evidence: {best.model} is {ratio:.1f}x cheaper and its interval "
                   f"{_fmt(best)} overlaps {chosen} {_fmt(c)}, but its mean is more than "
                   f"{MEAN_TOLERANCE} points lower. Add more samples to decide.", rejected)

