    lo = means[int(alpha / 2 * n_boot)]
    hi = means[min(n_boot - 1, int((1 - alpha / 2) * n_boot))]
    return mean, lo, hi


@dataclass
class ModelStats:
    model: str
    calls: int
    errors: int
    scored: int
    mean: float
    lo: float
    hi: float
    avg_latency_s: float
    avg_cost: float
