import json, os, time, urllib.request, urllib.error
from notbydefault.env import load_env; load_env()
P = {"groq": ("https://api.groq.com/openai/v1", "GROQ_API_KEY"), "gemini": ("https://generativelanguage.googleapis.com/v1beta/openai", "GEMINI_API_KEY")}
tests = [("groq","openai/gpt-oss-120b"),("groq","openai/gpt-oss-20b"),("groq","qwen/qwen3.8-27b"),
         ("gemini","gemini-2.5-pro"),("gemini","gemini-3.8-flash"),("gemini","gemini-3.5-flash-lite"),("gemini","gemini-3.1-flash-lite"),("gemini","gemma-4-31b-it")]
for prov, model in tests:
    base, key = P[prov]
    body = {"model": model, "messages": [{"role": "user", "content": "Reply with the single word: ok"}], "temperature": 0, "max_tokens": 200}
    req = urllib.request.Request(base + "/chat/completions", data=json.dumps(body).encode(),
        headers={"Authorization": f"Bearer {os.environ[key]}", "Content-Type": "application/json", "User-Agent": "notbydefault"})
    t = time.time()
    try:
        r = urllib.request.urlopen(req, timeout=60); d = json.loads(r.read())
        hdr = {k: v for k, v in r.headers.items() if k.lower().startswith("x-ratelimit")}
        msg = d["choices"][0]["message"]
        print(f"OK  {prov}/{model} {time.time()-t:.1f}s text={msg.get('content')!r:.30} usage={d.get('usage',{}).get('prompt_tokens')}/{d.get('usage',{}).get('completion_tokens')} fin={d['choices'][0].get('finish_reason')} {hdr}")
    except urllib.error.HTTPError as e:
        print(f"ERR {prov}/{model} HTTP {e.code} retry-after={e.headers.get('retry-after')} {e.read()[:400]!r}")
EOF

